// embedded n8n/lib/agent_config.js (drift-proof; test asserts equality)
// agent_config.js — Stage 4 central configuration contract (B1).
//
// ONE place resolves the entire agent runtime config from environment variables + safe defaults,
// so the operator never hand-edits a Spreadsheet ID (or any limit/flag) inside individual nodes.
// The orchestrator calls resolveConfig() once and passes the resolved object downstream; every other
// workflow receives config from the request record instead of carrying its own copy.
//
// NO secrets live here or in workflow JSON. Credentials (Google/Telegram/Claude/Apify) stay in the
// n8n credential store; this module only resolves NON-secret runtime settings + the spreadsheet id
// (an id, not a secret) from $env. In a Code node call it as resolveConfig($env) — the harness shims
// $env as {} so the same code runs offline.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) && str(v) !== '' ? n : d; }
function bool(v, d) {
  if (v === true) return true;
  if (v === false) return false;
  const s = str(v).toLowerCase();
  if (s === 'true' || s === 'yes' || s === '1') return true;
  if (s === 'false' || s === 'no' || s === '0') return false;
  return d;
}
function list(v) { return str(v).split(/[\s,;]+/).filter(Boolean); }

// Production-safe defaults: fail-closed (approval + source-health required), website-only allowlist,
// LLM features OFF, tight budgets. Everything is overridable by env or explicit override.
const DEFAULTS = {
  spreadsheet_id: '',
  telegram_allowed_user_ids: [],
  max_sources_per_request: 3,
  max_items_per_source: 25,
  max_external_calls: 40,
  source_budget_usd: 0.20,
  llm_budget_usd: 0.50,
  default_region: 'Москва/МО',
  default_niche: 'credit_brokerage',
  source_allowlist: ['website'],
  require_approval: true,
  require_source_health: true,
  enable_llm_planner: false,
  enable_llm_summary: false,
  report_data_mode: 'live',
  // ---- Stage 4 free-path / zero-paid-call guards (all fail-closed) -------------------------------------------
  // Telegram conversation is allowed; every PAID external action is OFF by default. The free path runs the full
  // conversation -> plan -> approval -> persistence loop while making zero paid calls. `max_external_calls` (above)
  // is the master kill-switch: 0 means no paid source/LLM call can occur even after approval.
  timezone: 'Europe/Moscow',
  enable_telegram: true,
  enable_external_actions: false,   // master switch for any paid collection/analysis
  enable_claude: false,             // Claude (planner/summary) only when explicitly enabled
  enable_apify: false,
  enable_firecrawl: false,
  enable_vk: false,
  monitoring_enabled: false,
  weekly_digest_enabled: false
};

// Map env var -> resolved config. Unknown/blank env falls back to DEFAULTS; explicit overrides win last.
function resolveConfig(env, overrides) {
  env = env || {};
  overrides = overrides || {};
  const allowedUsers = list(env.MS_TELEGRAM_ALLOWED_USER_IDS);
  const allowlist = list(env.MS_SOURCE_ALLOWLIST).map(s => s.toLowerCase());
  const cfg = {
    spreadsheet_id: str(env.MS_SPREADSHEET_ID) || DEFAULTS.spreadsheet_id,
    telegram_allowed_user_ids: (allowedUsers.length ? allowedUsers : DEFAULTS.telegram_allowed_user_ids).map(String),
    max_sources_per_request: num(env.MS_MAX_SOURCES, DEFAULTS.max_sources_per_request),
    max_items_per_source: num(env.MS_MAX_ITEMS_PER_SOURCE, DEFAULTS.max_items_per_source),
    max_external_calls: num(env.MS_MAX_EXTERNAL_CALLS, DEFAULTS.max_external_calls),
    source_budget_usd: num(env.MS_SOURCE_BUDGET_USD, DEFAULTS.source_budget_usd),
    llm_budget_usd: num(env.MS_LLM_BUDGET_USD, DEFAULTS.llm_budget_usd),
    default_region: str(env.MS_DEFAULT_REGION) || DEFAULTS.default_region,
    default_niche: str(env.MS_DEFAULT_NICHE) || DEFAULTS.default_niche,
    source_allowlist: allowlist.length ? allowlist : DEFAULTS.source_allowlist.slice(),
    require_approval: bool(env.MS_REQUIRE_APPROVAL, DEFAULTS.require_approval),
    require_source_health: bool(env.MS_REQUIRE_SOURCE_HEALTH, DEFAULTS.require_source_health),
    enable_llm_planner: bool(env.MS_ENABLE_LLM_PLANNER, DEFAULTS.enable_llm_planner),
    enable_llm_summary: bool(env.MS_ENABLE_LLM_SUMMARY, DEFAULTS.enable_llm_summary),
    report_data_mode: str(env.MS_REPORT_DATA_MODE) || DEFAULTS.report_data_mode,
    timezone: str(env.MS_TIMEZONE) || DEFAULTS.timezone,
    enable_telegram: bool(env.MS_ENABLE_TELEGRAM, DEFAULTS.enable_telegram),
    enable_external_actions: bool(env.MS_ENABLE_EXTERNAL_ACTIONS, DEFAULTS.enable_external_actions),
    enable_claude: bool(env.MS_ENABLE_CLAUDE, DEFAULTS.enable_claude),
    enable_apify: bool(env.MS_ENABLE_APIFY, DEFAULTS.enable_apify),
    enable_firecrawl: bool(env.MS_ENABLE_FIRECRAWL, DEFAULTS.enable_firecrawl),
    enable_vk: bool(env.MS_ENABLE_VK, DEFAULTS.enable_vk),
    monitoring_enabled: bool(env.MS_MONITORING_ENABLED, DEFAULTS.monitoring_enabled),
    weekly_digest_enabled: bool(env.MS_WEEKLY_DIGEST_ENABLED, DEFAULTS.weekly_digest_enabled)
  };
  for (const k in overrides) {
    if (Object.prototype.hasOwnProperty.call(overrides, k)) cfg[k] = overrides[k];
  }
  // fail-closed reconciliation: Claude master switch gates the LLM features; the external-actions master switch
  // (or a zero call ceiling) forces the effective paid-call budget to zero so no approval can spend.
  if (!cfg.enable_claude) { cfg.enable_llm_planner = false; cfg.enable_llm_summary = false; }
  cfg.zero_paid_mode = (cfg.enable_external_actions !== true) || (Number(cfg.max_external_calls) <= 0);
  cfg.effective_max_external_calls = cfg.zero_paid_mode ? 0 : Number(cfg.max_external_calls);
  // completeness check the orchestrator surfaces in the execution summary — never starts paid work blind
  cfg.missing = [];
  if (!cfg.spreadsheet_id) cfg.missing.push('MS_SPREADSHEET_ID');
  if (!cfg.telegram_allowed_user_ids.length) cfg.missing.push('MS_TELEGRAM_ALLOWED_USER_IDS');
  cfg.config_complete = cfg.missing.length === 0;
  return cfg;
}

function isAllowedUser(cfg, userId) {
  return ((cfg && cfg.telegram_allowed_user_ids) || []).indexOf(String(userId)) >= 0;
}
function sourceAllowed(cfg, source) {
  return ((cfg && cfg.source_allowlist) || []).indexOf(String(source).toLowerCase()) >= 0;
}
// true only when a PAID external action may run: external actions enabled AND a positive call ceiling.
// This is the single fail-closed predicate the orchestrator/monitor consult before any paid call.
function paidCallsAllowed(cfg) {
  return !!(cfg && cfg.enable_external_actions === true && Number(cfg.max_external_calls) > 0);
}
// per-collector gate: paid calls must be globally allowed AND the specific collector enabled AND on the allowlist.
function collectorEnabled(cfg, source) {
  if (!paidCallsAllowed(cfg)) return false;
  const s = String(source).toLowerCase();
  const flag = { website: 'enable_firecrawl', firecrawl: 'enable_firecrawl', apify: 'enable_apify', avito: 'enable_apify', vk: 'enable_vk' }[s];
  return sourceAllowed(cfg, s) && (flag ? cfg[flag] === true : false);
}
function llmAllowed(cfg) { return !!(cfg && cfg.enable_claude === true && (cfg.enable_llm_planner === true || cfg.enable_llm_summary === true)); }
// machine-readable free-path snapshot for the execution summary / tests.
function freePathStatus(cfg) {
  return {
    zero_paid_mode: !!(cfg && cfg.zero_paid_mode),
    enable_telegram: !!(cfg && cfg.enable_telegram),
    paid_calls_allowed: paidCallsAllowed(cfg),
    llm_allowed: llmAllowed(cfg),
    effective_max_external_calls: cfg ? Number(cfg.effective_max_external_calls) : 0,
    collectors: { firecrawl: collectorEnabled(cfg, 'website'), apify: collectorEnabled(cfg, 'apify'), vk: collectorEnabled(cfg, 'vk') }
  };
}
// --- end embedded agent_config ---

// --- node driver ---
var __env=(typeof $env!=='undefined'&&$env)?$env:{};
return [{json:resolveConfig(__env)}];

// embedded n8n/lib/telegram_io.js (drift-proof; test asserts equality)
// telegram_io.js — Stage 4 Telegram gateway + delivery outbox helpers (B2 + B8).
//
// Inbound: parse a Telegram update into a normalized intake record, decide authorization, build a
// duplicate-proof idempotency key (a re-delivered update_id must create exactly ONE request).
// Outbound: an outbox record keyed by a payload hash so retries never double-send the user-visible
// answer; plus safe Markdown escaping and message chunking for Telegram's 4096-char limit.

function str(v) { return v == null ? '' : String(v).trim(); }

// --- inbound -------------------------------------------------------------------------------------------
// Parse a raw Telegram update (message / callback_query) into the fields the gateway persists.
function parseUpdate(update) {
  update = update || {};
  const msg = update.message || update.edited_message || null;
  const cb = update.callback_query || null;
  let kind = 'unknown', text = '', chatId = '', userId = '', messageId = '', callbackData = '';
  if (cb) {
    kind = 'callback';
    callbackData = str(cb.data);
    userId = str(cb.from && cb.from.id);
    chatId = str(cb.message && cb.message.chat && cb.message.chat.id);
    messageId = str(cb.message && cb.message.message_id);
  } else if (msg) {
    text = str(msg.text);
    userId = str(msg.from && msg.from.id);
    chatId = str(msg.chat && msg.chat.id);
    messageId = str(msg.message_id);
    if (/^\/status\b/.test(text)) kind = 'status';
    else if (/^\/cancel\b/.test(text)) kind = 'cancel';
    else if (/^\//.test(text)) kind = 'command';
    else kind = 'request';
  }
  return {
    kind: kind,
    update_id: str(update.update_id),
    chat_id: chatId,
    user_id: userId,
    message_id: messageId,
    text: text,
    callback_data: callbackData
  };
}

function isAuthorized(parsed, allowedUserIds) {
  const ids = (allowedUserIds || []).map(String);
  return ids.indexOf(str(parsed && parsed.user_id)) >= 0;
}

// One Telegram update => one idempotency key. A redelivered update_id maps to the same key.
function updateIdempotencyKey(parsed) {
  parsed = parsed || {};
  return ['tg', str(parsed.update_id) || ('m' + str(parsed.message_id)), str(parsed.chat_id)].join('::');
}

// Callback payloads: approve:<agent_request_id> / reject:<agent_request_id>.
function parseCallback(data) {
  const m = str(data).match(/^(approve|reject|cancel):(.+)$/);
  if (!m) return { action: '', agent_request_id: '' };
  return { action: m[1], agent_request_id: str(m[2]) };
}
function approvalKeyboard(agentRequestId) {
  return { inline_keyboard: [[
    { text: '✅ Запустить', callback_data: 'approve:' + str(agentRequestId) },
    { text: '✖ Отклонить', callback_data: 'reject:' + str(agentRequestId) }
  ]] };
}

// --- outbound ------------------------------------------------------------------------------------------
// Telegram MarkdownV2 reserved chars. Escaping keeps user/report text from breaking the message.
function escapeMarkdown(text) {
  return str(text).replace(/([_*\[\]()~`>#+\-=|{}.!\\])/g, '\\$1');
}

// Split into <=limit chunks on line boundaries where possible (Telegram hard-caps at 4096).
function chunkMessage(text, limit) {
  limit = limit || 3900;
  const s = String(text == null ? '' : text);
  if (s.length <= limit) return [s];
  const out = [];
  let buf = '';
  for (const line of s.split('\n')) {
    if ((buf + '\n' + line).length > limit) {
      if (buf) out.push(buf);
      if (line.length > limit) { for (let i = 0; i < line.length; i += limit) out.push(line.slice(i, i + limit)); buf = ''; }
      else buf = line;
    } else { buf = buf ? (buf + '\n' + line) : line; }
  }
  if (buf) out.push(buf);
  return out;
}

// djb2 — small, stable, dependency-free hash for the outbox dedupe key.
function payloadHash(s) {
  s = String(s == null ? '' : s);
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return 'h' + h.toString(16);
}

// Build an outbox row. delivery_id is deterministic in (agent_request_id, report_id, payload) so the
// same answer can never be enqueued/sent twice for the same request+report.
function makeDelivery(agentRequestId, reportId, chatId, payload) {
  const hash = payloadHash(payload);
  return {
    delivery_id: ['dlv', str(agentRequestId) || 'req', str(reportId) || 'rep', hash].join('_'),
    agent_request_id: str(agentRequestId),
    report_id: str(reportId),
    chat_id: str(chatId),
    payload_hash: hash,
    chunks: chunkMessage(payload).length,
    send_status: 'pending',
    attempts: 0,
    telegram_message_id: '',
    last_error: ''
  };
}

// Idempotent enqueue: if an existing delivery has the same delivery_id and is already sent, skip.
function shouldSend(existingDeliveries, delivery) {
  const prior = (existingDeliveries || []).filter(d => str(d.delivery_id) === str(delivery.delivery_id));
  if (prior.some(d => str(d.send_status) === 'sent')) return { send: false, reason: 'already_sent' };
  return { send: true, reason: '' };
}
// --- end embedded telegram_io ---

// --- node driver ---
var body=($json&&$json.body)?$json.body:$json;
var parsed=parseUpdate(body);
var cfg=$('Resolve Agent Config').first().json;
parsed.authorized=isAuthorized(parsed,cfg.telegram_allowed_user_ids);
parsed.idempotency_key=updateIdempotencyKey(parsed);
return [{json:parsed}];

// embedded n8n/lib/intent_router.js (drift-proof; test asserts equality)
// intent_router.js — Part 2: natural-language intent router.
//
// Free-form conversation is the primary interface; buttons are optional accelerators. Routing is
// deterministic-first: obvious commands/callbacks and clear keyword phrases resolve with no LLM. Genuinely
// ambiguous free text is handed to a GUARDED Claude classifier whose JSON is validated against a strict
// schema; anything invalid/unsupported falls back to ONE clarification question. No external collection may
// start from an unvalidated intent. Standalone (no cross-lib require) so it embeds cleanly into a Code node.

function str(v) { return v == null ? '' : String(v).trim(); }
function low(v) { return str(v).toLowerCase(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : d; }

// The ONLY routable intent IDs (mirrors agent_charter capability IDs + the request-lifecycle callbacks). A
// contract test asserts this set stays in sync with the capability registry.
const INTENT_IDS = [
  'competitor_search', 'deep_competitor_analysis', 'clarify_request', 'report_followup', 'generate_ideas',
  'add_source', 'manage_sources', 'compare_periods', 'rerun_request', 'status', 'cancel', 'help', 'manage_memory',
  // reporting UX intents (operate on the last report / stored data)
  'export_report', 'show_chart', 'show_evidence', 'filter_report', 'refresh_sources', 'weekly_digest', 'manage_digest'
];
const REQUESTED_ACTIONS = ['build_plan', 'answer_from_context', 'manage_sources', 'manage_memory', 'approve', 'reject', 'status', 'cancel', 'help', 'clarify'];
const APPROVAL_INTENTS = ['competitor_search', 'deep_competitor_analysis', 'rerun_request', 'refresh_sources'];
const CONTEXT_INTENTS = ['deep_competitor_analysis', 'report_followup', 'generate_ideas', 'compare_periods', 'add_source', 'manage_sources', 'rerun_request',
  'export_report', 'show_chart', 'show_evidence', 'filter_report'];
// reporting intents that only make sense once a report exists (same guard as report_followup/ideas/compare)
const HISTORY_REQUIRED_INTENTS = ['report_followup', 'generate_ideas', 'compare_periods', 'export_report', 'show_chart', 'show_evidence', 'filter_report'];

// Keyword rules — literal Russian/English (NO \w/\b on Cyrillic). Ordered: most specific first.
const TEXT_RULES = [
  // --- reporting UX rules first (most specific) so they win over generic search/source rules ---
  ['weekly_digest', /недельн[а-яё]*\s*сводк|сводк[а-яё]*\s*за\s*недел|что\s*измен[а-яё]*\s*за\s*(эту\s*)?недел|за\s*эту\s*неделю|weekly\s*digest/i],
  ['manage_digest', /(включ|выключ|отключ|enable|disable|turn (on|off)).{0,25}(еженедельн|недельн|сводк|digest)|(еженедельн[а-яё]*\s*отчёт)/i],
  ['export_report', /пришли\s*таблиц|таблиц[ауы]|экспорт|выгруз|скачать|сделай\s*(excel|эксель|таблиц)|\bexcel\b|\bxlsx\b|\bcsv\b|в\s*файл/i],
  ['show_chart', /график|диаграмм|chart|визуализ|построй\s*(график|диаграмм)/i],
  ['show_evidence', /доказательств|пруф[ыов]?|evidence|цитат[аыу]|подтвержден[а-яё]*\s*(фактом|источник)/i],
  ['refresh_sources', /(обнов[а-яё]*|пересобери|собери\s*заново|refresh|пере-?проверь).{0,30}(устаревш|источник|данны|сайт)|обнови\s*(только\s*)?устаревш/i],
  ['filter_report', /(покажи|оставь|только|фильтр|отфильтр|отсортир|сортир).{0,40}(ставк|%|процент|ниже|выше|дешевле|дороже|качеств|healthy|degraded|акци)|ставк[аи]\s*(ниже|выше|меньше|больше)/i],
  ['deep_competitor_analysis', /подробн|глубж|глубок|детальн|разбери|deep (dive|analy)|in more detail/i],
  ['compare_periods', /сравн[а-яё]*\s*(с\s*)?(прошл|предыдущ|раньше|last|previous|прошлым)|по сравнению с прошл/i],
  ['generate_ideas', /иде[ия]|придум|адаптир|adapt|what ideas|ideas (we|to)|контент-?план/i],
  ['add_source', /(добав|подключ|включ|add|track|мониторинг).{0,30}(сайт|канал|сообществ|источник|telegram|телеграм|vk|вконтакте|http|url)|добавь (их|это|этот)/i],
  ['manage_sources', /(покажи|список|list|какие).{0,20}источник|tracked sources|пауз|останов|возобнов|resume|pause|убери источник|удали источник|проверь источник|поставь.{0,10}паузу/i],
  ['rerun_request', /запусти.{0,10}снова|повтор|сделай снова|again|rerun|перезапус|next week|на след/i],
  ['report_followup', /(что по|расскажи (о|про)|объясни|подробнее о|поясни|explain|what about|tell me about).{0,40}(конкурент|перв|втор|компан|first|second|them|их)/i],
  ['competitor_search', /найд|поищ|ищ[уи]|подбери|find|search|конкурент|competitor|рынок|market/i],
  ['help', /умеешь|умеете|что ты можешь|какие возможност|что ещё|what (can|else)|\bhelp\b|помощь|capabilit/i]
];

function entityExtract(text, ctx) {
  const t = low(text);
  ctx = ctx || {};
  const refs = [];
  if (/перв(ых|ые)?\s*дв|first two|обоих|оба|двух/i.test(t)) refs.push('first_two');
  else {
    if (/первого|первый|первой|first one|the first|номер один|№?\s*1/i.test(t)) refs.push('first');
    if (/второго|второй|second|номер два|№?\s*2/i.test(t)) refs.push('second');
  }
  if (/(этого|того|тот|that|this) (конкурент|competitor|компан)/i.test(t)) refs.push('that');
  if (/\b(их|them|those|these|эти[хм]?)\b/i.test(t) && !refs.length) refs.push('selected');
  if (/прошл[ыо][йм]?\s*отч[её]т|previous report|last report|предыдущ[а-яё]*\s*отч/i.test(t)) refs.push('previous_report');

  const platforms = [];
  if (/сайт|website|firecrawl|http|url|страниц/i.test(t)) platforms.push('website');
  if (/telegram|телеграм|тг|tg|канал/i.test(t)) platforms.push('telegram_channel');
  if (/vk|вконтакте|сообществ/i.test(t)) platforms.push('vk_community');

  let region = null;
  if (/москв|moscow|мо\b|msk/i.test(t)) region = 'Москва/МО';
  else if (/питер|спб|петербург|spb/i.test(t)) region = 'Санкт-Петербург';

  const refresh = /обнов|refresh|свеж|заново собери|пересобери|re-?collect/i.test(t);
  return { competitor_refs: refs, platforms: platforms, region: region, service: null, refresh: refresh };
}

// Resolve contextual references ("first_two", "them", "previous_report") against L1 state / last report.
function resolveReferences(entities, ctx) {
  entities = entities || {}; ctx = ctx || {};
  const competitors = (ctx.last_report && Array.isArray(ctx.last_report.competitors)) ? ctx.last_report.competitors : [];
  const selected = Array.isArray(ctx.selected_competitors) ? ctx.selected_competitors : [];
  const out = { competitors: [], report_id: null, unresolved: [] };
  for (const r of (entities.competitor_refs || [])) {
    if (r === 'first_two') out.competitors = competitors.slice(0, 2);
    else if (r === 'first') out.competitors = out.competitors.concat(competitors.slice(0, 1));
    else if (r === 'second') out.competitors = out.competitors.concat(competitors.slice(1, 2));
    else if (r === 'selected') out.competitors = selected.length ? selected.slice() : competitors.slice();
    else if (r === 'that') out.competitors = selected.length ? selected.slice(0, 1) : competitors.slice(0, 1);
    else if (r === 'previous_report') out.report_id = str(ctx.previous_report_id) || str(ctx.comparison_baseline_id);
    else out.unresolved.push(r);
  }
  // de-dup by company_name/ref
  const seen = {}; out.competitors = out.competitors.filter(c => {
    const k = str((c && (c.company_name || c.ref || c)) || ''); if (!k || seen[k]) return false; seen[k] = 1; return true;
  });
  return out;
}

function buildIntent(intentId, conf, entities, ctx) {
  const requiresContext = CONTEXT_INTENTS.indexOf(intentId) >= 0;
  const requiresApproval = APPROVAL_INTENTS.indexOf(intentId) >= 0;
  let action = 'answer_from_context';
  if (APPROVAL_INTENTS.indexOf(intentId) >= 0) action = 'build_plan';
  else if (intentId === 'add_source' || intentId === 'manage_sources') action = 'manage_sources';
  else if (intentId === 'manage_memory') action = 'manage_memory';
  else if (intentId === 'status') action = 'status';
  else if (intentId === 'cancel') action = 'cancel';
  else if (intentId === 'help') action = 'help';
  else if (intentId === 'clarify_request') action = 'clarify';
  return {
    intent: intentId, confidence: num(conf, 0.6), entities: entities || {},
    requires_context: requiresContext, requires_approval: requiresApproval, requested_action: action
  };
}

// Deterministic resolution. Returns an intent object, or null if the free text is genuinely ambiguous.
function deterministicIntent(parsed, ctx) {
  parsed = parsed || {}; ctx = ctx || {};
  const kind = str(parsed.kind);
  // 1. callbacks (button shortcuts) — always deterministic. Two forms:
  //    approve|reject|cancel:<arid>  -> request lifecycle
  //    intent|act:<capability_id>    -> a button equivalent to typing that intent
  if (kind === 'callback') {
    const data = low(parsed.callback_data);
    const life = data.match(/^(approve|reject|cancel):/);
    if (life) {
